import React from 'react';

interface AppLogoProps {
  className?: string;
}

// SLATE's mark: three schedule rows on a near-black tile -- today's duty in
// full white, the rest of the week receding. Inline SVG so it stays crisp at
// any size; matches the PWA/app icons generated by scripts/build-icons.mjs.
export const AppLogo: React.FC<AppLogoProps> = ({ className = 'h-9 w-9' }) => (
  <svg viewBox="0 0 512 512" className={className} xmlns="http://www.w3.org/2000/svg" role="img" aria-label="SLATE">
    <defs>
      <linearGradient id="slateLogoBg" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor="#1c1c1f" />
        <stop offset="0.55" stopColor="#000000" />
      </linearGradient>
    </defs>
    <rect width="512" height="512" rx="112" fill="url(#slateLogoBg)" />
    <rect x="3" y="3" width="506" height="506" rx="109" fill="none" stroke="#ffffff" strokeOpacity="0.14" strokeWidth="6" />
    <rect x="128" y="150" width="256" height="52" rx="26" fill="#ffffff" />
    <rect x="128" y="230" width="196" height="52" rx="26" fill="#ffffff" fillOpacity="0.55" />
    <rect x="128" y="310" width="136" height="52" rx="26" fill="#ffffff" fillOpacity="0.28" />
    <circle cx="358" cy="336" r="26" fill="#ffffff" fillOpacity="0.55" />
  </svg>
);
